}

export function parseArgs(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (isHelpToken(token)) {
      throw new CliExit(0, { stdout: formatHelp(programName) });
    }

    if (!token.startsWith('--')) {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const spec = ARGUMENTS_BY_FLAG.get(flag);

    if (!spec) {
      extras.push(token);
      continue;
    }

    let rawValue = '';

    if (equalsIndex === -1) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || isOptionLikeToken(nextToken)) {
