  }

  const missingFlags = ARGUMENT_SPECS.filter((spec) => !(spec.name in values)).map(
    (spec) => spec.flag,
  );

  if (missingFlags.length > 0) {
    throw new CliExit(2, {
      stderr: formatError(
        programName,
        `the following arguments are required: ${missingFlags.join(', ')}`,
