function chooseQuote(value) {
  if (!value.includes("'")) {
    return "'";
  }

  if (!value.includes('"')) {
    return '"';
  }

  return "'";
}

function escapeString(value, quote) {
  let escaped = '';

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      escaped += '\\\\';
    } else if (char === '\n') {
      escaped += '\\n';
    } else if (char === '\r') {
      escaped += '\\r';
    } else if (char === '\t') {
      escaped += '\\t';
    } else if (char === '\b') {
      escaped += '\\b';
    } else if (char === '\f') {
      escaped += '\\f';
    } else if (char === quote) {
      escaped += `\\${quote}`;
    } else if (codePoint < 32 || codePoint === 127) {
      escaped += `\\x${codePoint.toString(16).padStart(2, '0')}`;
    } else {
      escaped += char;
    }
  }

  return escaped;
}

export function toPythonStringLiteral(value) {
  const quote = chooseQuote(value);
  return `${quote}${escapeString(value, quote)}${quote}`;
}

export function toPythonRepr(value) {
  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError('Non-finite numbers are not supported.');
    }

    return Object.is(value, -0) ? '-0.0' : String(value);
  }

  if (typeof value === 'string') {
    return toPythonStringLiteral(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const parts = Object.entries(value).map(
      ([key, item]) => `${toPythonStringLiteral(key)}: ${toPythonRepr(item)}`,
    );
    return `{${parts.join(', ')}}`;
  }

  throw new TypeError(`Unsupported value type: ${typeof value}`);
}

