const PYTHON_INT_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/;

export function isPythonIntLiteral(value) {
  return PYTHON_INT_PATTERN.test(value);
}

export function parsePythonInt(value) {
  if (!isPythonIntLiteral(value)) {
    return null;
  }

  const normalized = value.replace(/_/g, '');
  const sign = normalized[0] === '+' || normalized[0] === '-' ? normalized[0] : '';
  const digits = sign === '' ? normalized : normalized.slice(1);
  const parsed = BigInt(digits);

  return sign === '-' ? -parsed : parsed;
}

